===== src/pricing.ts =====
 1 │ export type Zone = "PL" | "EU" | "WORLD";
 2 │ 
 3 │ /**
 4 │  * Koszt dostawy zamowienia w zlotych.
 5 │  * Regula biznesowa: docs/SPEC.md, sekcja 1.
 6 │  */
 7 │ export function calculateShipping(
 8 │   weightKg: number,
 9 │   zone: string,
10 │   isPremium: boolean,
11 │ ): number {
12 │   if (!Number.isFinite(weightKg)) {
13 │     throw new TypeError("weight must be a finite number");
14 │   }
15 │   if (weightKg <= 0) {
16 │     throw new RangeError("weight must be positive");
17 │   }
18 │   if (weightKg > 100) {
19 │     throw new RangeError("weight above carrier limit");
20 │   }
21 │ 
22 │   let base: number;
23 │   if (zone === "PL") {
24 │     base = 12;
25 │   } else if (zone === "EU") {
26 │     base = 29;
27 │   } else {
28 │     base = 79;
29 │   }
30 │ 
31 │   if (weightKg > 30) {
32 │     base = base + 40;
33 │   } else if (weightKg > 10) {
34 │     base = base + 15;
35 │   }
36 │ 
37 │   if (isPremium) {
38 │     base = base * 0.8;
39 │   }
40 │ 
41 │   return Math.round(base * 100) / 100;
42 │ }
===== src/invoiceId.ts =====
 1 │ export interface InvoiceId {
 2 │   year: number;
 3 │   month: number;
 4 │   seq: number;
 5 │ }
 6 │ 
 7 │ /**
 8 │  * Parsuje identyfikator faktury na czesci skladowe.
 9 │  * Regula biznesowa: docs/SPEC.md, sekcja 2.
10 │  */
11 │ export function parseInvoiceId(raw: string): InvoiceId {
12 │   if (typeof raw !== "string") {
13 │     throw new TypeError("invoice id must be a string");
14 │   }
15 │ 
16 │   const match = /^FV\/(\d{4})\/(0[1-9]|1[0-2])\/(\d{4})$/.exec(raw.trim());
17 │   if (match === null) {
18 │     throw new Error("malformed invoice id");
19 │   }
20 │ 
21 │   const year = Number(match[1]);
22 │   const month = Number(match[2]);
23 │   const seq = Number(match[3]);
24 │ 
25 │   if (year < 2000 || year > 2100) {
26 │     throw new RangeError("year out of supported range");
27 │   }
28 │   if (seq === 0) {
29 │     throw new RangeError("sequence number must not be zero");
30 │   }
31 │ 
32 │   return { year, month, seq };
33 │ }
===== src/loyalty.ts =====
 1 │ const VIP_THRESHOLD_PLN = 5000;
 2 │ const POINTS_CAP = 5000;
 3 │ 
 4 │ /**
 5 │  * Punkty lojalnosciowe przyznane za zamowienie.
 6 │  * Regula biznesowa: docs/SPEC.md, sekcja 3.
 7 │  */
 8 │ export function awardPoints(
 9 │   orderValuePLN: number,
10 │   lifetimeSpendPLN: number,
11 │ ): number {
12 │   if (!Number.isFinite(orderValuePLN) || !Number.isFinite(lifetimeSpendPLN)) {
13 │     throw new TypeError("amounts must be finite numbers");
14 │   }
15 │   if (orderValuePLN < 0 || lifetimeSpendPLN < 0) {
16 │     throw new RangeError("amounts must not be negative");
17 │   }
18 │ 
19 │   let points = Math.floor(orderValuePLN / 10);
20 │ 
21 │   if (lifetimeSpendPLN > VIP_THRESHOLD_PLN) {
22 │     points = points * 2;
23 │   }
24 │ 
25 │   if (points > POINTS_CAP) {
26 │     return POINTS_CAP;
27 │   }
28 │   return points;
29 │ }
===== src/cart.ts =====
 1 │ interface CartLine {
 2 │   sku: string;
 3 │   priceGrosz: number;
 4 │   qty: number;
 5 │ }
 6 │ 
 7 │ const COUPONS: Record<string, number> = {
 8 │   SAVE10: 10,
 9 │   HALF: 50,
10 │ };
11 │ 
12 │ /**
13 │  * Koszyk zakupowy.
14 │  * Regula biznesowa: docs/SPEC.md, sekcja 4.
15 │  */
16 │ export class Cart {
17 │   private lines: CartLine[] = [];
18 │   private discountPct = 0;
19 │ 
20 │   add(sku: string, priceGrosz: number, qty: number): void {
21 │     if (!Number.isInteger(priceGrosz) || priceGrosz < 0) {
22 │       throw new RangeError("price must be a non-negative integer of grosz");
23 │     }
24 │     if (!Number.isInteger(qty) || qty <= 0) {
25 │       throw new RangeError("quantity must be a positive integer");
26 │     }
27 │ 
28 │     const existing = this.lines.find((line) => line.sku === sku);
29 │     if (existing === undefined) {
30 │       this.lines.push({ sku, priceGrosz, qty });
31 │     } else {
32 │       existing.qty = existing.qty + qty;
33 │     }
34 │   }
35 │ 
36 │   /** Zdejmuje wskazana liczbe sztuk z koszyka. */
37 │   remove(sku: string, qty: number): void {
38 │     if (!Number.isInteger(qty) || qty <= 0) {
39 │       throw new RangeError("quantity must be a positive integer");
40 │     }
41 │ 
42 │     const existing = this.lines.find((line) => line.sku === sku);
43 │     if (existing === undefined) {
44 │       throw new Error("sku not in cart");
45 │     }
46 │     existing.qty = existing.qty - qty;
47 │   }
48 │ 
49 │   applyCoupon(code: string): void {
50 │     const pct = COUPONS[code];
51 │     if (pct === undefined) {
52 │       throw new Error("unknown coupon");
53 │     }
54 │     if (this.lines.length === 0) {
55 │       throw new Error("cannot apply coupon to an empty cart");
56 │     }
57 │     this.discountPct = pct;
58 │   }
59 │ 
60 │   /** Wartosc koszyka w groszach. */
61 │   total(): number {
62 │     let subtotal = 0;
63 │     for (const line of this.lines) {
64 │       if (line.qty < 0) {
65 │         throw new RangeError("cart quantity underflow");
66 │       }
67 │       subtotal = subtotal + line.priceGrosz * line.qty;
68 │     }
69 │     const discounted = (subtotal * (100 - this.discountPct)) / 100;
70 │     return Math.round(discounted);
71 │   }
72 │ }

